{
  "assessment_record": {
    "file_id": "UW-H-55033",
    "domain": "hospitality",
    "source": "underwriter_workflow",
    "content": {
      "policy_reference": "Hospitality Risk Scoring Guide v3.1",
      "rating_logic": "Extract guest sentiment score (1-5) from review text. Use the Guest Sentiment Decoder Table. 1=Unusable/Refund, 2=Major Flaw, 3=Mixed, 4=Good w/ Minor Issue, 5=Excellent/Repurchase. Score is based on the net functional assessment of the stay, not just politeness.",
      "Guest_Sentiment_Decoder_Table": [
        {
          "level": 1,
          "name": "Unusable/Refund",
          "cues": ["uninhabitable", "demand refund", "could not stay", "forced to leave", "complete failure", "waste of money"]
        },
        {
          "level": 2,
          "name": "Major Flaw",
          "cues": ["broken", "filthy", "noise all night", "did not work", "major problem", "advertised feature missing"]
        },
        {
          "level": 3,
          "name": "Mixed",
          "cues": ["but", "however", "on the other hand", "pros and cons", "good and bad", "mixed feelings"]
        },
        {
          "level": 4,
          "name": "Good w/ Minor Issue",
          "cues": ["great except", "excellent but", "perfect except for", "loved it but", "minor issue", "small complaint"]
        },
        {
          "level": 5,
          "name": "Excellent/Repurchase",
          "cues": ["perfect", "flawless", "will return", "highly recommend", "exceeded expectations", "best ever"]
        }
      ],
      "precedence_rules": "Rule A: A review containing cues from multiple levels must be assigned the lowest level for which a strong cue is present, UNLESS a later 'EDIT' or 'UPDATE' section explicitly and conclusively overrides the earlier sentiment, in which case the post-edit sentiment governs. Rule B: Numerical ratings (e.g., '3/5 stars') in the text are to be ignored if they contradict the textual cue analysis.",
      "review_data": {
        "original_post": "Stayed at the Mountain Lodge for a conference. The location is incredibly convenient—just a 5-minute walk to the convention center, which was the main reason I booked. The room itself was a letdown. It felt tired and the furniture was scuffed. The biggest issue was the bed; it was uncomfortably hard, and I woke up with back pain. The bathroom, however, was very clean and modern. The WiFi was strong and reliable, which I needed for work. So, a real mix of good and bad. I'd give it a 3 out of 5.",
        "user_edit": "[EDIT - next day]: I should add that after I posted this, the front desk manager called me personally. She was very concerned about my feedback on the bed and offered to move me to a different room with a newer mattress for the remainder of my stay. I declined as I was checking out, but the gesture was appreciated. It doesn't change the fact that the bed was bad, but the service recovery effort was good. My 3/5 rating stands.",
        "metadata_discrepancy": "Note: Internal property scorecard for this room lists 'Bed Quality Index' as 4.2/5, but guest says 'uncomfortably hard'. Guest's stated star rating in text (3/5) conflicts with internal metric."
      }
    }
  }
}

