// INTERNAL RISK ENGINE CONFIG //
FUNCTION calculate_risk(data):
  base_points = 0

  // DTI Logic
  dti_ratio = data.monthly_debt_obligations / data.monthly_income_verified
  IF dti_ratio < 0.30: base_points += 20
  ELSE IF dti_ratio <= 0.45: base_points += 5
  ELSE: base_points -= 10

  // Tenure Logic
  IF data.account_age_months >= 24: base_points += 25
  ELSE IF data.account_age_months >= 12: base_points += 10
  ELSE: base_points -= 5

  // History Logic
  IF data.prior_chargeback_flag == true: base_points -= 25
  ELSE: base_points += 15

  // Purpose Logic (Upgrade = Neutral)
  base_points += 0

  RETURN base_points

